<?php

declare(strict_types=1);

require __DIR__ . '/config/database.php';
require __DIR__ . '/includes/functions.php';

$kelasId = get_int_query('id');
$class = table_exists('view_kelas_lengkap')
    ? fetch_one('SELECT * FROM view_kelas_lengkap WHERE kelas_id = :kelas_id', ['kelas_id' => $kelasId])
    : fetch_one("SELECT k.*, d.nama_dosen, d.dosen_id, m.nama_matakuliah, m.semester, m.sks, sm.mean_likert_avg, sk.corr_Q1, sk.corr_Q2, sk.corr_Q3, sk.corr_Q4, sk.corr_Q5, sk.corr_Q6, sk.corr_Q7, sk.corr_Q8, sk.corr_Q9, sk.corr_Q10, sk.corr_Q11, sk.corr_Q12, sk.corr_Q13, sk.corr_Q14, r.total_essays, r.priority_q, r.secondary_q, r.strength_q, r.monitoring_q, r.main_q, r.main_category, r.main_recommendation FROM kelas k JOIN dosen d ON d.dosen_id = k.dosen_id JOIN matakuliah m ON m.matakuliah_id = k.matakuliah_id LEFT JOIN statistik_mean_kelas sm ON sm.kelas_id = k.kelas_id LEFT JOIN statistik_korelasi_kelas sk ON sk.kelas_id = k.kelas_id LEFT JOIN rekomendasi_kelas r ON r.kelas_id = k.kelas_id WHERE k.kelas_id = :kelas_id", ['kelas_id' => $kelasId]);

if ($class === null) {
    http_response_code(404);
    exit('Data kelas tidak ditemukan.');
}

$aspects = fetch_all('SELECT q AS aspek, mean_likert, correlation, mention_count, mention_rate, positive_count, neutral_count, negative_count, category, recommendation FROM priority_matrix_kelas WHERE kelas_id = :kelas_id ORDER BY ' . aspect_order_sql('q'), ['kelas_id' => $kelasId]);
$sentiment = normalize_sentiment_distribution($class);
$avgCorrelation = average_q_columns($class, 'corr_Q');
$essayTableAvailable = table_exists('essay_mahasiswa');
$essayPerPage = 20;
$essayPageValue = filter_input(INPUT_GET, 'esai_page', FILTER_VALIDATE_INT);
$essayPage = $essayPageValue === false || $essayPageValue === null ? 1 : max(1, (int) $essayPageValue);
$essayTotal = 0;
$essayTotalPages = 1;
$essayRows = [];

if ($essayTableAvailable) {
    $essayTotal = (int) (fetch_one('SELECT COUNT(*) AS total FROM essay_mahasiswa WHERE kelas_id = :kelas_id', ['kelas_id' => $kelasId])['total'] ?? 0);
    $essayTotalPages = max(1, (int) ceil($essayTotal / $essayPerPage));
    $essayPage = min($essayPage, $essayTotalPages);
    $essayOffset = ($essayPage - 1) * $essayPerPage;
    $essayRows = fetch_all("SELECT id, essay_original, essay_clean, sentimen, confidence, aspek_list, predicted_labels FROM essay_mahasiswa WHERE kelas_id = :kelas_id ORDER BY id LIMIT {$essayPerPage} OFFSET {$essayOffset}", ['kelas_id' => $kelasId]);
}

$essayStart = $essayTotal === 0 ? 0 : (($essayPage - 1) * $essayPerPage) + 1;
$essayEnd = min($essayTotal, $essayPage * $essayPerPage);
$pageTitle = 'Detail ' . ($class['nama_kelas'] ?: 'Kelas ' . $kelasId);

require __DIR__ . '/includes/header.php';
require __DIR__ . '/includes/navbar.php';
?>
<main class="container py-4">
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><div class="d-flex gap-3 no-print mb-2"><a href="javascript:history.back()" class="text-decoration-none">Kembali</a><a href="index.php" class="text-decoration-none">Beranda</a></div><h1 class="h3 mt-2 mb-1"><?= e($class['nama_kelas'] ?: 'Kelas ' . $kelasId) ?></h1><p class="text-secondary mb-0"><a href="detail_matakuliah.php?id=<?= (int) $class['matakuliah_id'] ?>" class="link-primary text-decoration-none"><?= e($class['nama_matakuliah']) ?></a> - ID kelas <?= (int) $kelasId ?></p></div><div class="d-flex gap-2 no-print"><a class="btn btn-primary" href="statistik.php?type=kelas&id=<?= (int) $kelasId ?>">Lihat statistik</a><button class="btn btn-outline-secondary" type="button" onclick="window.print()">Cetak</button></div></div>
    <section class="row g-3 mb-4"><div class="col-md-6 col-xl-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Dosen pengampu</div><?php if (!empty($class['dosen_id'])): ?><a class="fw-semibold mt-2 d-inline-block text-decoration-none" href="detail_dosen.php?id=<?= (int) $class['dosen_id'] ?>"><?= e($class['nama_dosen'] ?: 'Dosen ID ' . $class['dosen_id']) ?> <span class="text-secondary">(ID <?= (int) $class['dosen_id'] ?>)</span></a><?php else: ?><div class="fw-semibold mt-2">Belum tersedia</div><?php endif; ?></div></div></div><div class="col-md-6 col-xl-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Semester / SKS</div><div class="metric-value mt-2"><?= e($class['semester'] ?? '-') ?> / <?= e($class['sks'] ?? '-') ?></div></div></div></div><div class="col-md-6 col-xl-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Jumlah mahasiswa</div><div class="metric-value mt-2"><?= format_integer($class['jumlah_mahasiswa'] ?? 0) ?></div></div></div></div><div class="col-md-6 col-xl-3"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Jumlah esai</div><div class="metric-value mt-2"><?= format_integer($class['total_essays'] ?? $class['jumlah_essay'] ?? 0) ?></div></div></div></div></section>
    <section class="row g-4 mb-4"><div class="col-lg-5"><div class="card content-card h-100"><div class="card-body p-4"><h2 class="h5">Distribusi sentimen</h2><?php foreach ([['positive','Positif','bg-success'],['neutral','Netral','bg-secondary'],['negative','Negatif','bg-danger']] as $item): ?><div class="d-flex justify-content-between mt-3"><span><?= e($item[1]) ?></span><strong><?= number_format($sentiment[$item[0]], 1, ',', '.') ?>%</strong></div><div class="progress"><div class="progress-bar <?= e($item[2]) ?>" style="width: <?= e($sentiment[$item[0]]) ?>%"></div></div><?php endforeach; ?></div></div></div><div class="col-lg-7"><div class="card content-card recommendation-box h-100"><div class="card-body p-4"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><div class="small-label">Rekomendasi utama</div><h2 class="h4 mt-1 mb-0"><?= e($class['main_q'] ?? 'Belum tersedia') ?> - <?= e(q_description($class['main_q'] ?? null)) ?></h2></div><span class="badge align-self-start <?= e(category_badge($class['main_category'] ?? null)) ?>"><?= e(category_label($class['main_category'] ?? null)) ?></span></div><p class="mb-3"><?= e($class['main_recommendation'] ?? 'Rekomendasi untuk kelas ini belum tersedia.') ?></p><dl class="row mb-0 small"><dt class="col-sm-4">Prioritas</dt><dd class="col-sm-8"><?= e($class['priority_q'] ?? '-') ?></dd><dt class="col-sm-4">Perbaikan sekunder</dt><dd class="col-sm-8"><?= e($class['secondary_q'] ?? '-') ?></dd><dt class="col-sm-4">Kekuatan</dt><dd class="col-sm-8"><?= e($class['strength_q'] ?? '-') ?></dd><dt class="col-sm-4">Pemantauan</dt><dd class="col-sm-8"><?= e($class['monitoring_q'] ?? '-') ?></dd></dl></div></div></div></section>
    <section class="row g-3 mb-4"><div class="col-md-4"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Mean nilai akademik</div><div class="metric-value mt-2"><?= format_decimal($class['mean_nilai'] ?? null, 2) ?></div></div></div></div><div class="col-md-4"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Mean Likert keseluruhan</div><div class="metric-value mt-2"><?= format_decimal($class['mean_likert_avg'] ?? null, 2) ?></div></div></div></div><div class="col-md-4"><div class="card metric-card h-100"><div class="card-body"><div class="small-label">Rata-rata korelasi Q-nilai</div><div class="metric-value mt-2"><?= format_decimal($avgCorrelation, 3) ?></div></div></div></div></section>
    <section class="card content-card"><div class="card-body p-4"><h2 class="h5 mb-1">Detail analisis Q1-Q14</h2><p class="text-secondary">Ringkasan hasil kuantitatif, sentimen, pemetaan aspek, dan rekomendasi pada setiap indikator.</p><?php if ($aspects === []): ?><div class="alert alert-light border mb-0">Data aspek kelas belum tersedia.</div><?php else: ?><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Aspek</th><th>Deskripsi</th><th>Mean</th><th>Korelasi</th><th>Dibahas</th><th>Sentimen (+/0/-)</th><th>Kategori</th><th>Rekomendasi</th></tr></thead><tbody><?php foreach ($aspects as $aspect): ?><tr><td class="fw-semibold"><?= e($aspect['aspek']) ?></td><td class="aspect-description"><?= e(q_description($aspect['aspek'])) ?></td><td><?= format_decimal($aspect['mean_likert'], 2) ?></td><td><?= format_decimal($aspect['correlation'], 3) ?></td><td><?= format_integer($aspect['mention_count']) ?> (<?= format_percent($aspect['mention_rate']) ?>)</td><td><?= format_integer($aspect['positive_count']) ?> / <?= format_integer($aspect['neutral_count']) ?> / <?= format_integer($aspect['negative_count']) ?></td><td><span class="badge <?= e(category_badge($aspect['category'])) ?>"><?= e(category_label($aspect['category'])) ?></span></td><td><?= e($aspect['recommendation'] ?: '-') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
    <section class="card content-card mt-4"><div class="card-body p-4"><div class="d-flex flex-wrap justify-content-between gap-2 mb-2"><div><h2 class="h5 mb-1">Daftar Esai Mahasiswa</h2><p class="text-secondary mb-0">Menampilkan 20 esai per halaman sebagai data pendukung sentimen dan pemetaan aspek.</p></div><?php if ($essayTableAvailable): ?><span class="badge text-bg-light align-self-start"><?= format_integer($essayStart) ?>-<?= format_integer($essayEnd) ?> dari <?= format_integer($essayTotal) ?> esai</span><?php endif; ?></div><?php if (!$essayTableAvailable): ?><div class="alert alert-light border mb-0">Tabel essay_mahasiswa belum tersedia pada database.</div><?php elseif ($essayRows === []): ?><div class="alert alert-light border mb-0">Belum ada esai mahasiswa untuk kelas ini.</div><?php else: ?><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>No.</th><th>Esai</th><th>Sentimen</th><th>Confidence</th><th>Aspek / label</th></tr></thead><tbody><?php foreach ($essayRows as $index => $essay): ?><?php $essayText = $essay['essay_clean'] ?: $essay['essay_original']; $labels = array_filter(array_map('trim', explode(',', (string) ($essay['aspek_list'] ?: $essay['predicted_labels'])))); ?><tr><td class="text-secondary"><?= format_integer($essayStart + $index) ?></td><td class="essay-text"><?= e($essayText) ?></td><td><span class="badge <?= e(sentiment_badge($essay['sentimen'] ?? null)) ?>"><?= e(ucfirst((string) ($essay['sentimen'] ?? '-'))) ?></span></td><td><?= format_percent($essay['confidence'] ?? 0, 2) ?></td><td class="essay-labels"><?php if ($labels === []): ?>-<?php else: ?><?php foreach ($labels as $label): ?><?php $labelText = strtolower($label) === 'general' ? 'General' : strtoupper($label); ?><span class="badge text-bg-primary"><?= e($labelText) ?></span><?php endforeach; ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if ($essayTotalPages > 1): ?><nav class="no-print" aria-label="Navigasi esai mahasiswa"><ul class="pagination justify-content-end mb-0"><li class="page-item <?= $essayPage <= 1 ? 'disabled' : '' ?>"><a class="page-link" href="detail_kelas.php?id=<?= (int) $kelasId ?>&esai_page=<?= max(1, $essayPage - 1) ?>">Sebelumnya</a></li><li class="page-item disabled"><span class="page-link">Halaman <?= format_integer($essayPage) ?> dari <?= format_integer($essayTotalPages) ?></span></li><li class="page-item <?= $essayPage >= $essayTotalPages ? 'disabled' : '' ?>"><a class="page-link" href="detail_kelas.php?id=<?= (int) $kelasId ?>&esai_page=<?= min($essayTotalPages, $essayPage + 1) ?>">Berikutnya</a></li></ul></nav><?php endif; ?><?php endif; ?></div></section>
</main>
<?php require __DIR__ . '/includes/footer.php'; ?>
